// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner != address(this) && nonOwner != address(c));
        vm.assume(nonOwner != address(0));
        amount = bound(amount, 1, 100 ether);

        vm.deal(address(this), amount);
        vm.prank(address(this));
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "Initial fund failed");

        uint256 balanceBefore = address(c).balance;

        vm.prank(nonOwner);
        (bool success,) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        assertEq(address(c).balance, balanceBefore);
    }
}
